# -*- coding: utf-8 -*-
#  게임용 파이썬(embeddable) 전용 보정입니다.
#
#  embeddable 배포판은 python312._pth 로 sys.path 를 고정하는데,
#  그 바람에 "스크립트가 있는 폴더" 가 sys.path 에서 빠집니다.
#  평범한 파이썬과 같게 만들어, 옆에 있는 .py 를 import 할 수 있게 합니다.
#
#  이 파일을 지우면 lab/w12_chart.py 같은 예제가 ModuleNotFoundError 를 냅니다.
import os
import sys

try:
    _here = None
    if len(sys.argv) > 0 and sys.argv[0] not in ("", "-c", "-m"):
        _here = os.path.dirname(os.path.abspath(sys.argv[0]))
    if _here and os.path.isdir(_here) and _here not in sys.path:
        sys.path.insert(0, _here)

    _cwd = os.getcwd()
    if _cwd not in sys.path:
        sys.path.insert(0, _cwd)
except Exception:
    pass
